package com.orbitcrm.shared.entity;

import java.time.Instant;
import java.util.UUID;

import jakarta.persistence.Column;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.PrePersist;
import jakarta.persistence.PreUpdate;
import jakarta.persistence.Version;

import com.orbitcrm.shared.util.UuidV7;

/**
 * Common superclass of all JPA entities: identity, timestamps and optimistic locking.
 *
 * <p>Purpose: avoid repeating the same infrastructure fields in every entity.
 * <ul>
 *   <li>{@code id}: a UUIDv7 generated by the application ({@link com.orbitcrm.shared.util.UuidV7}), so ids are
 *   time-ordered (index friendly) and cannot be guessed.</li>
 *   <li>{@code createdAt} / {@code updatedAt}: maintained by JPA lifecycle callbacks.</li>
 *   <li>{@code version}: {@code @Version} column for optimistic locking; a {@code null} version tells Spring Data
 *   that the entity is new, so {@code save} inserts instead of merging.</li>
 *   <li>Equality and hash code are based on the id.</li>
 * </ul>
 * Extended directly by non-tenant entities (tenants, sessions, tokens) and through {@link TenantScopedEntity} by
 * tenant-owned ones.
 *
 * @author Abhay
 */
@MappedSuperclass
public abstract class BaseEntity {

    @Id
    @Column(name = "id", nullable = false, updatable = false)
    private UUID id = UuidV7.generate();

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    @Version
    @Column(name = "version", nullable = false)
    private Long version;

    @PrePersist
    void onPersist() {
        Instant now = Instant.now();
        createdAt = now;
        updatedAt = now;
    }

    @PreUpdate
    void onUpdate() {
        updatedAt = Instant.now();
    }

    public UUID getId() {
        return id;
    }

    protected void assignId(UUID id) {
        this.id = id;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public Long getVersion() {
        return version;
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (other == null || getClass() != other.getClass()) {
            return false;
        }
        return id.equals(((BaseEntity) other).id);
    }

    @Override
    public int hashCode() {
        return id.hashCode();
    }
}
